using System.Diagnostics;using SobhanNotificationHub.Services;namespace SobhanNotificationHub.UI;public partial class DeviceConnectWindow:System.Windows.Window{public DeviceConnectWindow(){InitializeComponent();DeviceNameBox.Text=Environment.MachineName;}private async void Connect_Click(object s,RoutedEventArgs e){ConnectButton.IsEnabled=false;StatusText.Text="در حال اتصال...";try{var registration=new DeviceRegistrationService(App.Services.Api,App.Services.TokenStore);await registration.PairAsync(CodeBox.Text.Trim(),DeviceNameBox.Text.Trim(),CancellationToken.None);StatusText.Foreground=System.Windows.Media.Brushes.Green;StatusText.Text="اتصال با موفقیت انجام شد.";await ((App)System.Windows.Application.Current).StartConnectedAsync();Close();}catch(Exception ex){LoggingService.Error("pair_ui",ex);StatusText.Text=ex.Message;}finally{ConnectButton.IsEnabled=true;}}private void OpenSite_Click(object s,RoutedEventArgs e)=>Process.Start(new ProcessStartInfo(App.Services.Settings.SiteUrl.TrimEnd('/')+"/admin/notification-devices.php"){UseShellExecute=true});private void Cancel_Click(object s,RoutedEventArgs e)=>Close();}
